SELECT A.TRADE_DATE AS `交易日期`, M.CSNAME AS `股票名称`, M.COMB_SYMBOL AS `股票代码`, ROUND(A.OPEN_PRICE, 2) AS `开盘价(美元)`, ROUND(A.HIGH_PRICE, 2) AS `最高价(美元)`, ROUND(A.LOW_PRICE, 2) AS `最低价(美元)`, ROUND(A.CLOSE_PRICE, 2) AS `收盘价(美元)`, ROUND(A.CHG, 2) AS `涨跌额(美元)`, ROUND(A.CHG_PCT_DAY, 2) AS `涨跌幅(%)`, ROUND(A.TRADE_AMOUNT / 100000000, 2) AS `成交额(亿美元)`, ROUND(A.TRADE_VOLUME / 1000000, 2) AS `成交量(百万股)`, ROUND(A.TOTAL_SHARES / 100000000, 2) AS `总股本(亿股)` FROM VIEW_US_EOD_EXPR A JOIN AMERICAN_STOCK_MAIN M ON A.FIU_ID = M.FIU_ID WHERE M.CSNAME LIKE '%英伟达%' AND A.CLOSE_PRICE IS NOT NULL ORDER BY A.TRADE_DATE DESC LIMIT 1;
